 static int checks;static void Check(bool ok,string n){if(!ok)throw new Exception("P FAIL / "+n);checks++;Console.WriteLine("P PASS / "+n);}
 static DemoWorld Fresh(){var w=new DemoWorld();w.NewGame(0);w.WalletFunds=100000;w.Population.Enabled=false;return w;}
 static DemoWorld Reload(DemoWorld w){w.Save();var b=new DemoWorld();Check(b.Load(w.ActiveSavePath43),"Actual save reload");return b;}
 static EncounterF Start(DemoWorld w,ProfileP p){Check(w.IssueP(p.Id,p.Family=="Event"?"current-local-v1":"")=="","Costed issue / "+p.Id);w.Player.SetCombatHull(FleetCatalog.Source(p.Mode is "Scan" or "Neut" or "Salvage"?"Merlin":"Caracal").Id);w.Player.Shield=w.Player.MaxShield;w.Player.Armor=w.Player.MaxArmor;w.Player.Hull=w.Player.MaxHull;w.Player.Cap=w.Player.MaxCap;w.Undock();var e=w.Exploration.Encounters.Last();Check(w.EnterEncounterF("f:"+e.Id),"Physical admission / "+p.Id);Check(w.Targets.Any(t=>t.Id.StartsWith("f:"+e.Id+":guard")&&t.Alive),"Actual defenders / "+p.Id);Check(!e.PocketReady,"Entry cannot complete / "+p.Id);return e;}
 static void Guards(DemoWorld w){for(int a=0;a<4;a++){foreach(var t in w.Targets.Where(t=>t.Id.Contains(":guard")&&t.Alive).ToArray())w.DamageAuditF(t);w.EvaluateEncounterF(w.ActiveEncounterF!);}}
