 static void Finish(DemoWorld w,EncounterF e){Guards(w);w.EvaluateEncounterF(e);Check(e.PocketReady,"Physical objective ready / "+e.Template);w.Player.Position=w.Targets.First(t=>t.Id==$"f:{e.Id}:gate:0").Position;Check(w.AdvancePocketF(e.Id)==""&&e.State=="Completed","Completion gate / "+e.Template);decimal funds=w.Balance;w.CompleteP(e);Check(w.Balance==funds,"Once-only contribution settlement");}
 static void Utility(DemoWorld w,SpaceTarget t,string kind){var d=UtilityCatalog.All.First(d=>d.Kind==kind&&d.Size<=1);w.Player.Utilities[0]=new(){ModuleId=d.Id,Online=true,Repeat=false};w.Player.Position=t.Position;w.Player.Cap=w.Player.MaxCap;w.SelectedId=w.LockedId=t.Id;Check(w.ToggleUtility(0),"Fitted native utility starts / "+kind);w.UpdateUtility(d.Cycle+1);}
