 if(mode=="Artifact"){var cache=w.Targets.First(t=>t.Id.Contains(":artifact:"));w.Player.Position=cache.Position;w.SelectedId=cache.Id;Check(!w.LootUtilityTarget(),"Buried artifact protected");w.HarvestEncounterF(w.Targets.First(t=>t.Id.Contains(":ore:")),30);Check(w.LootUtilityTarget()&&w.CargoItems.GetValueOrDefault("p_artifact")==1,"Actual recovered artifact");Deliver(w,e);}
