 if(mode=="Salvage"){foreach(var t in w.Targets.Where(t=>t.Id.Contains(":research")).ToArray()){Utility(w,t,"Salvage");Check(t.Salvage==0&&t.Contents.GetValueOrDefault("p_research")==1,"Native finite salvage exposes actual research");w.SelectedId=t.Id;Check(w.LootUtilityTarget(),"Physical research collection");}Deliver(w,e);}
 Finish(w,e);w=Reload(w);Check(w.Exploration.Encounters.Last().RunP!.Settled,"Objective settlement reload / "+mode);}
 {var w=Fresh();var e=Start(w,CatalogP.All.First(p=>p.Mode=="Scan"));w.DamageAuditF(w.Targets.First(t=>t.Id.Contains(":civilian")));Check(e.State=="Failed","Civilian destruction terminal failure");}
